def features(item): # Build features using only physical inputs and topology, without family labels or response fields.
    path=RUN/'cases'/item['id'];data=np.load(path/'fields.npz');meta=json.loads((RUN/'meshes'/f"{item['family']}.json").read_text());receipt=json.loads((path/'receipt.json').read_text());assert receipt['status']=='VALID_CONVERGED' # Admit only independently checked physical labels.
    xyz=data['xyz'];tet=data['tet'];groups=data['groups'];extent=np.maximum(np.ptp(xyz,axis=0),1e-12);normalized=(xyz-xyz.min(axis=0))/extent;E=meta['E_MPa']*item['params'][3];force=data['f'];total=force.sum(axis=0);magnitude=max(float(np.linalg.norm(total)),1e-12);support=np.zeros_like(xyz);support.ravel()[data['fixed']]=1 # Recover actual geometry, constitutive scale, loading and prescribed degrees.
    fixed_nodes=np.unique(data['fixed']//3);fixed_spread=np.ptp(xyz[fixed_nodes],axis=0)/extent;axis=int(np.argmin(fixed_spread));load_axis=int(np.argmax(np.abs(total)));length=float(extent[axis]);volume=float(data['volume'].sum());area=volume/length # Derive clamped-axis and material measure from source geometry, never from family identity.
    centroid=xyz[tet[:,:4]].mean(axis=1);center=float(np.average(centroid[:,load_axis],weights=data['volume']));second=float(np.sum(data['volume']*(centroid[:,load_axis]-center)**2)/length);scale=magnitude*length/(E*area) if load_axis==axis else magnitude*length**3/(E*max(second,1e-12)) # Nondimensionalize response with an explicitly geometric elastic scale that is available for an unseen topology.
    scale=max(scale,1e-10);membership=np.zeros((len(xyz),2));membership[tet[groups==0].ravel(),0]=1 # Encode continuum material membership without naming structural families.
    if np.any(groups==1): membership[tet[groups==1].ravel(),1]=1 # Preserve steel/rubber interface membership where present.
    fourier=np.column_stack([function(normalized*frequency*np.pi) for frequency in [1.,2.] for function in [np.sin,np.cos]]);physical=np.tile(np.r_[np.log(extent/1000.),np.log(E/200000.),meta['nu'],total/magnitude],(len(xyz),1));distance=normalized[:,axis] # Use dimensionless geometry and actual load direction at each query point.
