    bins=np.minimum((normalized*np.array([4,3,3])).astype(int),[3,2,2]);raw=bins[:,0]*9+bins[:,1]*3+bins[:,2];labels,inverse=np.unique(raw,return_inverse=True);count=len(labels);coarse=np.zeros((36,query.shape[1]),np.float32);mask=np.zeros(36,np.float32);mask[:count]=1;adj=np.zeros((2,36,36),np.float32) # Pad only for batching while keeping variable actual node counts explicit.
