    held='deck' if mode=='leave_deck_out' else None;train=[i for i,s in enumerate(samples) if s['split']=='train' and s['family']!=held];validation=[i for i,s in enumerate(samples) if s['split']=='validation' and s['family']!=held];directory=OUT/mode/f'seed_{seed}';directory.mkdir(parents=True,exist_ok=True);torch.manual_seed(seed);rng=np.random.default_rng(seed);model=SharedOperator(samples[0]['query'].shape[1]);optimizer=torch.optim.AdamW(model.parameters(),lr=.002,weight_decay=1e-6);scheduler=torch.optim.lr_scheduler.CosineAnnealingLR(optimizer,epochs,eta_min=2e-5);best=None;best_score=float('inf');history=[];started=time.time();validation_batches=[batch(samples,validation[i:i+8],np.random.default_rng(999+i),256) for i in range(0,len(validation),8)] # Freeze validation spatial sampling independently of training and exclude every held-out topology label.
