    test_sample=next(s for s in samples if s['split']=='test' and s['family']!=held);b=batch([test_sample],[0]);perm=np.random.default_rng(93).permutation(36);inverse_perm=np.argsort(perm);modified=dict(b);modified['coarse']=b['coarse'][:,perm];modified['mask']=b['mask'][:,perm];modified['adj']=b['adj'][:,:,perm][:,:,:,perm];modified['inverse']=torch.tensor(inverse_perm[b['inverse'].numpy()]) # Permute all graph nodes and remap physical query associations consistently.
